using Aurora.Core;
using Aurora.Editor;
using System.Text.RegularExpressions;
static class MaterialTerminatorChecks
{
 public static void Run(Action<bool,string> check,Action<Action,string> reject,string? native)
 {
  const string body="$SUBMATERIAL Paint\n$TEXTURE_MTL 0 paint.dds\n$CUSTOMVECTOR 3 1 2 3\n$DIFFUSECOLOR 1 1 1 1\n";
  const string tail="$END // retain\n$SUBMATERIAL Paint\n$TEXTURE_MTL 0 unreachable.dds\n$SUBMATERIAL Ghost\n$TEXTURE_MTL 0 missing.dds\n";string text=body+tail;
  check(NativeMaterialText.Names(text).SequenceEqual(new[]{"Paint"})&&NativeMaterialText.Property(text,"Paint","DIFFUSECOLOR")!.SequenceEqual(new float[]{1,1,1,1}),"native materials ignore duplicate names and properties after the first terminator");
  var changed=NativeMaterialText.SetProperty(text,"Paint","DIFFUSECOLOR",[.5f,.5f,.5f,1]);check(changed.EndsWith(tail,StringComparison.Ordinal)&&changed.Contains("$CUSTOMVECTOR 3 1 2 3"),"native material edits preserve the entire inactive suffix and unknown active fields");int copied=0;var mapped=VehicleAssets.MapMaterial(text,r=>{copied++;if(r!="paint.dds")throw new Exception("Unreachable map copied");return "local.dds";});check(copied==1&&mapped.EndsWith(tail,StringComparison.Ordinal),"material asset export only resolves reachable textures and preserves inactive text");
  var appended=NativeMaterialText.Append(text,NativeMaterialText.Create(["New"],"a.dds","b.dds","n.dds"));check(NativeMaterialText.Names(appended).SequenceEqual(new[]{"Paint","New"})&&appended[VehicleScript.ActiveLength(appended)..]==tail,"new material is inserted before the first terminator, not inside an inactive appended document");
  var glass=NativeMaterialText.Duplicate(text,"Paint","Aurora_Glass");check(NativeMaterialText.Names(glass).SequenceEqual(new[]{"Paint","Aurora_Glass"})&&glass[VehicleScript.ActiveLength(glass)..]==tail&&NativeMaterialText.Property(glass,"Aurora_Glass","DIFFUSECOLOR")!.SequenceEqual(new float[]{1,1,1,1}),"glass material duplication stays before the first terminator and preserves inactive duplicate source blocks");
  var normalized=NativeMaterialText.Normalize(body+"\n\n"+body+"$END\n");check(Regex.Matches(normalized,@"(?m)^\$SUBMATERIAL").Count==1&&normalized.Contains("$CUSTOMVECTOR 3 1 2 3"),"identical active duplicate material blocks normalize without losing custom fields");reject(()=>NativeMaterialText.Normalize(body+body.Replace("1 1 1 1","0 0 0 1")+"$END\n"),"conflicting duplicate material blocks require repair instead of guessing precedence");
  var repeatedProperties=NativeMaterialText.Normalize(body+"$SUBMATERIAL Paint\n$DIFFUSECOLOR 1 1 1 1\n$END\n");check(Regex.Matches(repeatedProperties,@"(?m)^\$SUBMATERIAL").Count==1&&repeatedProperties.Contains("$TEXTURE_MTL 0 paint.dds")&&repeatedProperties.Contains("$CUSTOMVECTOR 3 1 2 3"),"contained repeated material declarations preserve full texture and property definitions");
  string root=Path.Combine(Path.GetTempPath(),"Aurora-mtl-end-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{string file=Path.Combine(root,"material.mtl");File.WriteAllText(file,text);File.WriteAllBytes(Path.Combine(root,"paint.dds"),DdsImage.Encode(new(1,1,[255,255,255,255])));var maps=MaterialDocuments.Native(file);int exported=0;var result=MaterialExport.Render(text,file,maps,r=>{exported++;return Path.GetFileName(r);});check(maps.Keys.SequenceEqual(new[]{"Paint"})&&exported>=1&&result.Native.EndsWith(tail,StringComparison.Ordinal),"native import and serializer roundtrip a material with missing unreachable textures");}finally{Directory.Delete(root,true);}
  string paths=Path.Combine(Path.GetTempPath(),"Aurora-mtl-paths-"+Guid.NewGuid().ToString("N"));try{
   string mediaRoot=Path.Combine(paths,"media_soviet"),folder=Path.Combine(mediaRoot,"vehicles","test");Directory.CreateDirectory(folder);string mtl=Path.Combine(folder,"material.mtl");File.WriteAllBytes(Path.Combine(mediaRoot,"glass.dds"),[1]);File.WriteAllBytes(Path.Combine(folder,"glass.dds"),[2]);File.WriteAllText(mtl,"$SUBMATERIAL Local\n$TEXTURE_MTL 0 glass.dds\n$SUBMATERIAL Global\n$TEXTURE 0 glass.dds\n$END\n");
   var textures=MaterialDocuments.Native(mtl);check(File.ReadAllBytes(textures["Local"].Base!)[0]==2&&File.ReadAllBytes(textures["Global"].Base!)[0]==1,"native texture directive chooses the explicit local or game root even when both files exist");
   var entries=new Dictionary<string,byte[]>();string packed=VehicleAssets.Pack("$MATERIAL material.mtl\n$END\n",folder,entries);string restored=Path.Combine(paths,"restored");Directory.CreateDirectory(restored);foreach(var entry in entries){string target=Path.Combine(restored,entry.Key);Directory.CreateDirectory(Path.GetDirectoryName(target)!);File.WriteAllBytes(target,entry.Value);}string output=Path.Combine(paths,"export");Directory.CreateDirectory(output);VehicleAssets.Export(packed,restored,output);string exportedMtl=Directory.GetFiles(output,"*.mtl").Single();var restoredMaps=MaterialDocuments.Native(exportedMtl);check(File.ReadAllBytes(restoredMaps["Local"].Base!)[0]==2&&File.ReadAllBytes(restoredMaps["Global"].Base!)[0]==1,"packing and portable export preserve distinct local and game texture references");
   File.Delete(Path.Combine(mediaRoot,"glass.dds"));reject(()=>MaterialFiles.ResolveNative(mtl,"glass.dds",false),"missing game texture never silently substitutes an unrelated local texture");
  }finally{if(Directory.Exists(paths))Directory.Delete(paths,true);}
  if(native==null||VehicleAssets.Media(native) is not string media)return;foreach(string relative in new[]{"dlc3/vehicles/service_mixer_t24/material.mtl","vehicles/open_rmn_8135f/material_2.mtl"}){string file=Path.Combine(media,relative);if(!File.Exists(file))continue;var maps=MaterialDocuments.Native(file);check(maps.Count>0&&maps.Keys.Distinct().Count()==maps.Count,"native material with repeated or inactive blocks imports: "+relative);}
 }
}
